DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.bestelbot_advies_loggen(text,date,date,jsonb,text)'::regprocedure) INTO d; d:=replace(d,'FROM(SELECT trim(r->>''artikel'') artikel,sum((r->>''hoeveelheid'')::numeric) som,count(DISTINCT coalesce(r->>''eenheid'',''''))=1 AND count(DISTINCT coalesce(r->''gegevens'',''{}''))=1 vergelijkbaar FROM jsonb_array_elements(p_regels)r GROUP BY trim(r->>''artikel''))x','FROM(SELECT trim(j->>''artikel'') artikel,sum((j->>''hoeveelheid'')::numeric) som,count(DISTINCT coalesce(j->>''eenheid'',''''))=1 AND count(DISTINCT coalesce(j->''gegevens'',''{}''))=1 vergelijkbaar FROM jsonb_array_elements(p_regels)j GROUP BY trim(j->>''artikel''))x');EXECUTE d;END $$;